package com.videomind.module.agent.controller;import com.videomind.common.api.ApiResponse;import com.videomind.common.context.MockUserContext;import com.videomind.module.agent.service.MindAgentBindingService;import jakarta.servlet.http.HttpServletResponse;import java.io.IOException;import java.util.Map;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/integrations/mindagent")public class MindAgentBindingController{private final MindAgentBindingService service;private final com.videomind.module.agent.service.MindAgentVideoSyncService sync;private final com.videomind.module.auth.AuthProperties auth;public MindAgentBindingController(MindAgentBindingService s,com.videomind.module.agent.service.MindAgentVideoSyncService sync,com.videomind.module.auth.AuthProperties auth){service=s;this.sync=sync;this.auth=auth;}@GetMapping("/status")ApiResponse<?>status(){return ApiResponse.success(service.status(MockUserContext.currentUserId()));}@PostMapping("/authorize")ApiResponse<?>authorize(){return ApiResponse.success(Map.of("authorizationUrl",service.authorizationUrl(MockUserContext.currentUserId())));}@GetMapping("/callback")void callback(@RequestParam String code,@RequestParam String state,HttpServletResponse response)throws IOException{service.callback(MockUserContext.currentUserId(),code,state);response.sendRedirect(auth.getFrontendUrl()+"/?mindagent=bound");}@DeleteMapping("/binding")ApiResponse<?>unlink(){service.unlink(MockUserContext.currentUserId());return ApiResponse.success();}@PostMapping("/videos/{videoId}/sync")ApiResponse<?>sync(@PathVariable Long videoId){return ApiResponse.success(sync.sync(videoId,MockUserContext.currentUserId()));}}
